package nexusbench

import (
	"bytes"
	"context"
	"os/exec"
)

// Runner runs one kubectl command. args are the arguments after "kubectl" and
// carry no --context: the runner adds it. stdin is sent to the command when it
// is not empty. Both streams are returned even on failure, because the stderr
// of a failed call is what classifyKubectl reads.
type Runner interface {
	Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error)
}

// execRunner runs the kubectl found on PATH against one context.
type execRunner struct {
	path    string
	context string
}

// NewExecRunner finds kubectl on PATH and returns a Runner that passes
// "--context <kubeContext>" to every call. It fails with a KubectlMissing
// BenchError when kubectl is not installed. This is the one place of the
// package that starts a process.
func NewExecRunner(kubeContext string) (Runner, error) {
	path, err := exec.LookPath("kubectl")
	if err != nil {
		return nil, &BenchError{
			Kind:  KubectlMissing,
			Cause: "kubectl was not found on PATH",
			Check: "run `mise install` to get kubectl, then `kubectl version --client`",
			Err:   err,
		}
	}
	return &execRunner{path: path, context: kubeContext}, nil
}

// Run implements Runner.
func (r *execRunner) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
	full := append([]string{"--context", r.context}, args...)
	cmd := exec.CommandContext(ctx, r.path, full...) //nolint:gosec // the binary is the kubectl found on PATH and the arguments are built by this package from validated parameters
	if len(stdin) > 0 {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var out, errOut bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errOut
	err = cmd.Run()
	return out.Bytes(), errOut.Bytes(), err
}
package nexusbench

import "strings"

// ErrKind says which of the failures of the bench (D-F) a BenchError is. The
// zero value is Unclassified on purpose: an error nobody classified must not
// pass for the first named kind.
type ErrKind int

// The kinds of D-F, in the order the bench meets them.
const (
	// Unclassified is a failure none of the other kinds describes.
	Unclassified ErrKind = iota
	KubectlMissing
	ContextNotFound
	ClusterUnreachable
	Forbidden
	NamespaceForeign
	NamespaceMissing
	NodePortTaken
	AdmissionDenied
	PodPending
	ImagePull
	Crash
	Deadline
	RESTUnreachable
	ProvisionFailed
)

// BenchError is the one error type of the bench: a probable cause and what to
// check, both in English and both free of secrets. Err is the underlying error,
// kept for errors.Is and errors.As; Error never prints it, because the text of
// a failed sub-process can carry a credential.
type BenchError struct {
	Kind  ErrKind
	Cause string
	Check string
	Err   error
}

// Error returns "<Cause>. Check: <Check>".
func (e *BenchError) Error() string {
	return e.Cause + ". Check: " + e.Check
}

// Unwrap returns the underlying error, or nil when there is none.
func (e *BenchError) Unwrap() error { return e.Err }

// classifyKubectl maps the stderr of a failed kubectl call to a kind. The text
// of kubectl changes between versions, so this is a fallback for the cases the
// structured calls (exit status, JSON) cannot tell apart; a text it does not
// know is Unclassified.
func classifyKubectl(stderr string) ErrKind {
	s := strings.ToLower(stderr)
	switch {
	// The more specific reason wins: a webhook refusal is reported by the API
	// server as Forbidden too.
	case strings.Contains(s, "admission webhook") && strings.Contains(s, "denied"):
		return AdmissionDenied
	case strings.Contains(s, "provided port is already allocated"),
		strings.Contains(s, "provided port is not in the valid range"):
		return NodePortTaken
	case strings.Contains(s, "forbidden"):
		return Forbidden
	case strings.Contains(s, "unable to connect to the server"),
		strings.Contains(s, "connection refused"),
		strings.Contains(s, "i/o timeout"),
		strings.Contains(s, "tls handshake timeout"):
		return ClusterUnreachable
	}
	return Unclassified
}

// isNotFound reports whether stderr is the kubectl answer for an absent object.
func isNotFound(stderr string) bool {
	return strings.Contains(stderr, "(NotFound)")
}
package nexusbench

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"
)

// The tests here never reach a real kubectl: PATH is replaced by a directory
// that holds either nothing or a shell script standing in for kubectl, which
// records what it was given. They need no cluster, no network and no
// requireBench guard.

func TestNewExecRunnerKubectlMissing(t *testing.T) {
	// An empty directory as the whole PATH: no kubectl can be found, whatever
	// the host has installed.
	t.Setenv("PATH", t.TempDir())

	r, err := NewExecRunner("datomir")
	if err == nil {
		t.Fatal("NewExecRunner succeeded without kubectl on PATH")
	}
	if r != nil {
		t.Errorf("runner = %v, want nil on error", r)
	}
	var be *BenchError
	if !errors.As(err, &be) {
		t.Fatalf("error %T is not a *BenchError: %v", err, err)
	}
	if be.Kind != KubectlMissing {
		t.Errorf("Kind = %d, want KubectlMissing (%d)", be.Kind, KubectlMissing)
	}
	msg := err.Error()
	for _, want := range []string{"kubectl", "mise install"} {
		if !strings.Contains(msg, want) {
			t.Errorf("message %q does not mention %q", msg, want)
		}
	}
}

// fakeKubectlScript is a stand-in kubectl: it writes its arguments, one per
// line, and its standard input to the files named by the environment, answers
// on both streams and exits with the requested code.
const fakeKubectlScript = `#!/bin/sh
printf '%s\n' "$@" > "$KUBECTL_FAKE_ARGS"
cat > "$KUBECTL_FAKE_STDIN"
echo "stdout-line"
echo "stderr-line" >&2
exit "${KUBECTL_FAKE_EXIT:-0}"
`

type fakeKubectlBinary struct {
	argsFile, stdinFile string
}

// installFakeKubectl puts the script first on PATH and points it at two files
// of the test's temporary directory. The script needs a POSIX shell.
func installFakeKubectl(t *testing.T) fakeKubectlBinary {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("the stand-in kubectl is a POSIX shell script")
	}
	bin := t.TempDir()
	if err := os.WriteFile(filepath.Join(bin, "kubectl"), []byte(fakeKubectlScript), 0o755); err != nil { //nolint:gosec // an executable script is the point
		t.Fatalf("writing the stand-in kubectl: %v", err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))

	out := t.TempDir()
	b := fakeKubectlBinary{argsFile: filepath.Join(out, "args"), stdinFile: filepath.Join(out, "stdin")}
	t.Setenv("KUBECTL_FAKE_ARGS", b.argsFile)
	t.Setenv("KUBECTL_FAKE_STDIN", b.stdinFile)
	t.Setenv("KUBECTL_FAKE_EXIT", "0")
	return b
}

func (b fakeKubectlBinary) args(t *testing.T) []string {
	t.Helper()
	raw, err := os.ReadFile(b.argsFile)
	if err != nil {
		t.Fatalf("the stand-in kubectl was not run: %v", err)
	}
	return strings.Split(strings.TrimSuffix(string(raw), "\n"), "\n")
}

func (b fakeKubectlBinary) stdin(t *testing.T) string {
	t.Helper()
	raw, err := os.ReadFile(b.stdinFile)
	if err != nil {
		t.Fatalf("the stand-in kubectl was not run: %v", err)
	}
	return string(raw)
}

func TestExecRunnerInjectsTheContext(t *testing.T) {
	tests := []struct {
		name    string
		context string
		args    []string
		stdin   []byte
	}{
		{"read", "datomir", []string{"get", "pods", "-n", "nexus-bench"}, nil},
		{"apply with a manifest on stdin", "datomir", []string{"apply", "--server-side", "-f", "-"}, []byte("kind: Namespace\n")},
		{"another context", "k0s-lab", []string{"get", "nodes", "-o", "json"}, nil},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			bin := installFakeKubectl(t)
			r, err := NewExecRunner(tt.context)
			if err != nil {
				t.Fatalf("NewExecRunner: %v", err)
			}

			stdout, stderr, err := r.Run(context.Background(), tt.stdin, tt.args...)
			if err != nil {
				t.Fatalf("Run: %v", err)
			}

			want := append([]string{"--context", tt.context}, tt.args...)
			if got := bin.args(t); !slices.Equal(got, want) {
				t.Errorf("kubectl got %q, want %q", got, want)
			}
			if got := bin.stdin(t); got != string(tt.stdin) {
				t.Errorf("kubectl stdin = %q, want %q", got, tt.stdin)
			}
			if string(stdout) != "stdout-line\n" {
				t.Errorf("stdout = %q, want %q", stdout, "stdout-line\n")
			}
			if string(stderr) != "stderr-line\n" {
				t.Errorf("stderr = %q, want %q", stderr, "stderr-line\n")
			}
		})
	}
}

func TestExecRunnerKeepsBothStreamsOnFailure(t *testing.T) {
	installFakeKubectl(t)
	t.Setenv("KUBECTL_FAKE_EXIT", "3")
	r, err := NewExecRunner("datomir")
	if err != nil {
		t.Fatalf("NewExecRunner: %v", err)
	}

	stdout, stderr, err := r.Run(context.Background(), nil, "get", "pods")
	if err == nil {
		t.Fatal("Run succeeded although kubectl exited 3")
	}
	if string(stdout) != "stdout-line\n" || string(stderr) != "stderr-line\n" {
		t.Errorf("streams = %q / %q, want both kept for the classifier", stdout, stderr)
	}
}

func TestExecRunnerHonorsACancelledContext(t *testing.T) {
	installFakeKubectl(t)
	r, err := NewExecRunner("datomir")
	if err != nil {
		t.Fatalf("NewExecRunner: %v", err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	if _, _, err := r.Run(ctx, nil, "get", "pods"); err == nil {
		t.Error("Run succeeded on a cancelled context")
	}
}

package nexusbench

import (
	"errors"
	"fmt"
	"strings"
	"testing"
)

// namedKinds is every kind of the D-F table the tests refer to by name.
var namedKinds = []struct {
	name string
	kind ErrKind
}{
	{"KubectlMissing", KubectlMissing},
	{"ContextNotFound", ContextNotFound},
	{"ClusterUnreachable", ClusterUnreachable},
	{"Forbidden", Forbidden},
	{"NamespaceForeign", NamespaceForeign},
	{"NamespaceMissing", NamespaceMissing},
	{"NodePortTaken", NodePortTaken},
	{"AdmissionDenied", AdmissionDenied},
	{"PodPending", PodPending},
	{"ImagePull", ImagePull},
	{"Crash", Crash},
	{"Deadline", Deadline},
	{"RESTUnreachable", RESTUnreachable},
	{"ProvisionFailed", ProvisionFailed},
}

func TestErrKindsAreDistinct(t *testing.T) {
	seen := map[ErrKind]string{}
	for _, k := range namedKinds {
		if other, dup := seen[k.kind]; dup {
			t.Errorf("%s and %s share the value %d", k.name, other, k.kind)
		}
		seen[k.kind] = k.name
	}
}

func TestOpsAreDistinct(t *testing.T) {
	ops := map[string]Op{"OpUp": OpUp, "OpProvision": OpProvision, "OpDown": OpDown, "OpStatus": OpStatus}
	seen := map[Op]string{}
	for name, op := range ops {
		if other, dup := seen[op]; dup {
			t.Errorf("%s and %s share the value %d", name, other, op)
		}
		seen[op] = name
	}
}

func TestBenchErrorMessage(t *testing.T) {
	tests := []struct {
		name string
		err  *BenchError
		want string
	}{
		{
			name: "cause then check",
			err: &BenchError{
				Kind:  ContextNotFound,
				Cause: `no kubeconfig context named "datomir"`,
				Check: "kubectl config get-contexts",
			},
			want: `no kubeconfig context named "datomir". Check: kubectl config get-contexts`,
		},
		{
			name: "the wrapped error is not part of the message",
			err: &BenchError{
				Kind:  ClusterUnreachable,
				Cause: "the cluster does not answer",
				Check: "kubectl --context datomir get --raw /readyz",
				Err:   errors.New("exit status 1"),
			},
			want: "the cluster does not answer. Check: kubectl --context datomir get --raw /readyz",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.err.Error(); got != tt.want {
				t.Errorf("Error() = %q, want %q", got, tt.want)
			}
		})
	}
}

// A sub-process error can carry a secret in its text; Error() is what reaches
// the terminal, so it must never print the wrapped error.
func TestBenchErrorDoesNotEchoTheWrappedError(t *testing.T) {
	be := &BenchError{
		Kind:  ProvisionFailed,
		Cause: "Nexus refused the request",
		Check: "kubectl get pods",
		Err:   errors.New("exec failed: password=hunter2"),
	}
	if strings.Contains(be.Error(), "hunter2") {
		t.Errorf("Error() echoes the wrapped error: %q", be.Error())
	}
}

func TestBenchErrorUnwrap(t *testing.T) {
	sentinel := errors.New("sentinel")
	with := &BenchError{Kind: Crash, Cause: "c", Check: "k", Err: sentinel}
	if got := with.Unwrap(); got != sentinel {
		t.Errorf("Unwrap() = %v, want the wrapped error", got)
	}
	if !errors.Is(with, sentinel) {
		t.Error("errors.Is does not reach the wrapped error")
	}
	without := &BenchError{Kind: Crash, Cause: "c", Check: "k"}
	if got := without.Unwrap(); got != nil {
		t.Errorf("Unwrap() = %v, want nil when nothing is wrapped", got)
	}
	if errors.Is(without, sentinel) {
		t.Error("errors.Is matched a sentinel that was never wrapped")
	}
}

func TestBenchErrorAsThroughWrapping(t *testing.T) {
	var base error = &BenchError{Kind: Forbidden, Cause: "c", Check: "k"}
	wrapped := fmt.Errorf("preflight: %w", fmt.Errorf("again: %w", base))

	var be *BenchError
	if !errors.As(wrapped, &be) {
		t.Fatal("errors.As does not find the *BenchError")
	}
	if be.Kind != Forbidden {
		t.Errorf("Kind = %d, want Forbidden (%d)", be.Kind, Forbidden)
	}
}

func TestClassifyKubectl(t *testing.T) {
	tests := []struct {
		name   string
		stderr string
		want   ErrKind
	}{
		{
			name:   "connection refused behind Unable to connect",
			stderr: "Unable to connect to the server: dial tcp 192.168.1.31:6443: connect: connection refused\n",
			want:   ClusterUnreachable,
		},
		{
			name:   "TLS handshake timeout behind Unable to connect",
			stderr: "Unable to connect to the server: net/http: TLS handshake timeout\n",
			want:   ClusterUnreachable,
		},
		{
			name:   "i/o timeout behind Unable to connect",
			stderr: "Unable to connect to the server: dial tcp 192.168.1.31:6443: i/o timeout\n",
			want:   ClusterUnreachable,
		},
		{
			name:   "bare connection refused",
			stderr: "dial tcp 127.0.0.1:6443: connect: connection refused\n",
			want:   ClusterUnreachable,
		},
		{
			name:   "forbidden list",
			stderr: "Error from server (Forbidden): services is forbidden: User \"anthoni\" cannot list resource \"services\" in API group \"\" at the cluster scope\n",
			want:   Forbidden,
		},
		{
			name:   "forbidden namespace get",
			stderr: "Error from server (Forbidden): namespaces \"nexus-bench\" is forbidden: User \"anthoni\" cannot get resource \"namespaces\" in API group \"\" in the namespace \"nexus-bench\"\n",
			want:   Forbidden,
		},
		{
			name:   "Forbidden with a capital and nothing else",
			stderr: "Error from server (Forbidden): access refused by the gateway\n",
			want:   Forbidden,
		},
		{
			name:   "NodePort already allocated",
			stderr: "The Service \"nexus\" is invalid: spec.ports[0].nodePort: Invalid value: 30481: provided port is already allocated\n",
			want:   NodePortTaken,
		},
		{
			name:   "NodePort out of range",
			stderr: "The Service \"nexus\" is invalid: spec.ports[0].nodePort: Invalid value: 29999: provided port is not in the valid range. The range of valid ports is 30000-32767\n",
			want:   NodePortTaken,
		},
		{
			name:   "admission webhook denied",
			stderr: "Error from server: admission webhook \"validate.kyverno.svc-fail\" denied the request: resource Deployment/nexus-bench/nexus was blocked due to the following policies\n",
			want:   AdmissionDenied,
		},
		{
			// The more specific reason wins over the generic status.
			name:   "admission webhook denied reported as Forbidden",
			stderr: "Error from server (Forbidden): error when creating \"STDIN\": admission webhook \"x\" denied the request: nope\n",
			want:   AdmissionDenied,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := classifyKubectl(tt.stderr); got != tt.want {
				t.Errorf("classifyKubectl(%q) = %d, want %d", tt.stderr, got, tt.want)
			}
		})
	}
}

// An unknown stderr must not be mistaken for any kind of the table, and the
// zero value of ErrKind must not stand for "classified": the package needs one
// extra value, an "unclassified" kind, that none of the named kinds uses.
func TestClassifyKubectlUnknownIsNoNamedKind(t *testing.T) {
	for _, stderr := range []string{
		"",
		"error: unknown command \"frobnicate\" for \"kubectl\"\n",
		"Error from server (Conflict): Operation cannot be fulfilled on namespaces \"x\": the object has been modified\n",
	} {
		t.Run(stderr, func(t *testing.T) {
			got := classifyKubectl(stderr)
			for _, k := range namedKinds {
				if got == k.kind {
					t.Errorf("classifyKubectl(%q) = %s, but nothing in it says so", stderr, k.name)
				}
			}
		})
	}
}

1	package nexusbench
2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"slices"
11		"strconv"
12		"strings"
13		"testing"
14	)
15	
16	// Source guards of DEVDESK-504 (CA7). They read the package with go/parser and
17	// fail naming file and line, like internal/ui/keymap/*_scan_test.go:
18	//
19	//   - a test that reaches the real cluster, the bench descriptor or the secrets
20	//     path calls requireBench(t) first, so `mise run test` can never act on
21	//     datomir;
22	//   - nothing but kubectl.go and secrets.go starts a process, so the bench has
23	//     one door to the cluster (kubectl.go) and one to git (secrets.go);
24	//   - the credentials of the REST client are attached in one place and no code
25	//     names the Authorization header, so no log or error can carry it.
26	//
27	// Every detector has a self-test that feeds it a faulty source and a correct
28	// one held in memory. A failure of a guard points at code that breaks the rule,
29	// not at a test to relax. Limits are stated at each guard.
30	
31	// ---- parsing ----------------------------------------------------------------
32	
33	type parsedSource struct {
34		path string // slash-separated, relative to the package folder
35		fset *token.FileSet
36		file *ast.File
37	}
38	
39	func parseSource(t *testing.T, path, src string) parsedSource {
40		t.Helper()
41		fset := token.NewFileSet()
42		f, err := parser.ParseFile(fset, path, src, parser.SkipObjectResolution)
43		if err != nil {
44			t.Fatalf("parse %s: %v", path, err)
45		}
46		return parsedSource{path: path, fset: fset, file: f}
47	}
48	
49	func (p parsedSource) at(n ast.Node) string {
50		return p.path + ":" + strconv.Itoa(p.fset.Position(n.Pos()).Line)
51	}
52	
53	// packageSources parses the Go files of the package folder, and of the folders
54	// below it when recursive. Test files are kept or dropped as asked; testdata is
55	// never read.
56	func packageSources(t *testing.T, tests, recursive bool) []parsedSource {
57		t.Helper()
58		var out []parsedSource
59		err := filepath.WalkDir(".", func(path string, d fs.DirEntry, err error) error {
60			if err != nil {
61				return err
62			}
63			if d.IsDir() {
64				if path != "." && (!recursive || d.Name() == "testdata") {
65					return filepath.SkipDir
66				}
67				return nil
68			}
69			if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") != tests {
70				return nil
71			}
72			src, err := os.ReadFile(path) //nolint:gosec // a source file of this package, found by the walk above
73			if err != nil {
74				return err
75			}
76			out = append(out, parseSource(t, filepath.ToSlash(path), string(src)))
77			return nil
78		})
79		if err != nil {
80			t.Fatalf("read the package sources: %v", err)
81		}
82		if len(out) == 0 {
83			t.Fatal("the guard found no source file: it would pass on nothing")
84		}
85		return out
86	}
87	
88	// ---- guard 1: requireBench ---------------------------------------------------
89	
90	// benchGuardedCalls are the calls that reach the real bench: kubectl on PATH,
91	// the versioned descriptor that names the bench, the secrets path of the bench,
92	// and a REST client. A test (or helper) that makes one has to call
93	// requireBench(t) first, unless it is an exception below.
94	var benchGuardedCalls = []string{"NewExecRunner", "DescriptorPath", "DefaultSecretsPath", "newClient"}
95	
96	// benchException is a function allowed to make a guarded call without
97	// requireBench, because what it does cannot reach the bench. check, when set,
98	// verifies the reason in the source of the function, so the exception cannot
99	// outlive it.
100	type benchException struct {
101		reason string
102		check  func(*ast.FuncDecl) string
103	}
104	
105	// requireBenchExceptions are named, never matched by pattern. TestGuardExceptionsStillMatch
106	// fails when one stops matching a function that makes a guarded call.
107	var requireBenchExceptions = map[string]benchException{
108		// DescriptorPath is only compared with a path; the file is not read.
109		"TestDescriptorPath": {reason: "compares the path, reads no file"},
110		// A pure path computation over a map standing in for the environment.
111		"TestDefaultSecretsPath": {reason: "pure path computation", check: noRealEnvironment},
112		// The client of this test is only inspected by reflection; it never sends.
113		"TestNewClientSettings": {reason: "inspects the fields of a client that sends nothing"},
114		// The four tests of NewExecRunner run against an empty PATH or a shell
115		// script standing in for kubectl (installFakeKubectl).
116		"TestNewExecRunnerKubectlMissing":         {reason: "PATH is an empty folder", check: isolatesPath},
117		"TestExecRunnerInjectsTheContext":         {reason: "PATH leads to a fake kubectl script", check: isolatesPath},
118		"TestExecRunnerKeepsBothStreamsOnFailure": {reason: "PATH leads to a fake kubectl script", check: isolatesPath},
119		"TestExecRunnerHonorsACancelledContext":   {reason: "PATH leads to a fake kubectl script", check: isolatesPath},
120	}
121	
122	// callName returns the name a call is made under: f(...) or nexusbench.f(...).
123	func callName(call *ast.CallExpr) string {
124		switch fn := call.Fun.(type) {
125		case *ast.Ident:
126			return fn.Name
