283	func staleExceptions(exceptions map[string]benchException, used []string) []string {
284		var stale []string
285		for name := range exceptions {
286			if !slices.Contains(used, name) {
287				stale = append(stale, name)
288			}
289		}
290		slices.Sort(stale)
291		return stale
292	}
