238	// scanRequireBench checks every function of src that makes a guarded call.
239	func scanRequireBench(src parsedSource, exceptions map[string]benchException) benchScan {
240		var res benchScan
241		for _, decl := range src.file.Decls {
242			calls := guardedCalls(decl)
243			if len(calls) == 0 {
244				continue
245			}
246			// Only a plain function can be an exception: a method or a variable
247			// that shares the name of one does not inherit it.
248			name, fn := "", (*ast.FuncDecl)(nil)
249			if f, ok := decl.(*ast.FuncDecl); ok && f.Recv == nil {
250				name, fn = f.Name.Name, f
251			}
252			first := calls[0]
253			if guard, ok := firstRequireBench(decl); ok && guard < first.Pos() {
254				continue
255			}
256			what := callName(first) + " reaches the bench"
257			ex, excepted := exceptions[name]
258			switch {
259			case fn == nil || !excepted:
260				where := "outside a plain function"
261				if fn != nil {
262					where = "in " + name
263				}
264				res.findings = append(res.findings, src.at(first)+": "+what+" "+where+" without a requireBench(t) call before it")
265			default:
266				if problem := ex.run(fn); problem != "" {
267					res.findings = append(res.findings, src.at(first)+": exception for "+name+" no longer holds: "+problem)
268				}
269				res.excepted = append(res.excepted, name)
270			}
271		}
272		return res
273	}
