// gitIgnores reports whether git ignores path inside the working tree at root.
// It is a variable so a test can replace the one process the package starts for
// the guard; kubectl.go stays the only file that starts one otherwise.
var gitIgnores = func(root, path string) (bool, error) {
	ctx, cancel := context.WithTimeout(context.Background(), gitCheckTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "-C", root, "check-ignore", "-q", "--", path) //nolint:gosec // fixed arguments, the paths come from the caller's own configuration
	cmd.Env = gitEnvironment()
	err := cmd.Run()
	if err == nil {
		return true, nil // exit 0: the path is ignored
	}
	var exit *exec.ExitError
	if errors.As(err, &exit) && exit.ExitCode() == 1 {
		return false, nil // exit 1: the path is not ignored
	}
	return false, err // git missing, exit 128 (not a repository, bad path), timeout
}

// gitEnvironment is the environment of the git process: the caller's, without
// the variables that point git at a repository or inject a configuration.
// Inherited, GIT_DIR and its siblings would make git judge another repository
// than the one holding the path; GIT_CONFIG_COUNT/KEY/VALUE and
// GIT_CONFIG_PARAMETERS could add a core.excludesFile that ignores the secrets
// file; GIT_CEILING_DIRECTORIES could hide the repository. The user and system
// configuration are switched off, so only the rules of the repository itself
// (.gitignore, .git/info/exclude) can say a path is ignored. Names are compared
// in upper case because Windows environment names are case-insensitive.
func gitEnvironment() []string {
	var env []string
	for _, kv := range os.Environ() {
		name, _, _ := strings.Cut(kv, "=")
		upper := strings.ToUpper(name)
		switch upper {
		case "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR", "GIT_OBJECT_DIRECTORY", "GIT_NAMESPACE",
			"GIT_CONFIG_PARAMETERS", "GIT_CONFIG_COUNT", "GIT_CONFIG_GLOBAL", "GIT_CONFIG_SYSTEM", "GIT_CONFIG_NOSYSTEM",
			"GIT_CEILING_DIRECTORIES":
			continue
		}
		if strings.HasPrefix(upper, "GIT_CONFIG_KEY_") || strings.HasPrefix(upper, "GIT_CONFIG_VALUE_") {
			continue
		}
		env = append(env, kv)
	}
	return append(env, "GIT_CONFIG_GLOBAL="+os.DevNull, "GIT_CONFIG_NOSYSTEM=1")
}

// Load implements SecretStore. The error never carries the content of the
// file: a corrupt file may hold a password.
func (s *fileStore) Load() (Secrets, bool, error) {
	f, err := os.Open(s.path)
	if errors.Is(err, fs.ErrNotExist) {
		return Secrets{}, false, nil
	}
	if err != nil {
		return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
	}
	defer func() { _ = f.Close() }()
	info, err := f.Stat()
	if err != nil {
		return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
	}
	// Windows has no group or other bits to read.
	if runtime.GOOS != "windows" && info.Mode().Perm()&0o077 != 0 {
		return Secrets{}, false, &BenchError{
			Cause: fmt.Sprintf("the secrets file %s can be read by other accounts (mode %04o)", s.path, info.Mode().Perm()),
			Check: "chmod 600 " + s.path,
		}
	}
	data, err := io.ReadAll(f)
	if err != nil {
		return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
	}
	var out Secrets
	if err := json.Unmarshal(data, &out); err != nil {
		return Secrets{}, false, &BenchError{
			Cause: fmt.Sprintf("the secrets file %s is not valid", s.path),
			Check: "delete the file and run the bench again, or restore it from a copy; its content is not shown",
			Err:   err,
		}
	}
	return out, true, nil
}

// Save implements SecretStore.
func (s *fileStore) Save(secrets Secrets) error {
	data, err := json.MarshalIndent(secrets, "", "  ")
	if err != nil {
		return fmt.Errorf("encode the secrets: %w", err)
	}
	return writeFileAtomic(s.path, append(data, '\n'), secretsFileMode, secretsDirMode)
}

// Remove implements SecretStore. It deletes the file, then its folder when
// that is empty; a folder that holds anything else stays.
func (s *fileStore) Remove() error {
	if err := os.Remove(s.path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove the secrets file: %w", err)
	}
	dir := filepath.Dir(s.path)
	entries, err := os.ReadDir(dir)
	if errors.Is(err, fs.ErrNotExist) || (err == nil && len(entries) > 0) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read the secrets folder: %w", err)
	}
	if err := os.Remove(dir); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove the secrets folder: %w", err)
	}
	return nil
}

// writeFileAtomic writes data to path through a temporary file of the same
// folder and a rename, so a reader sees the old file or the new one, never a
// partial one. Missing folders are created with dirMode. The temporary file is
// removed when anything fails. The error text holds paths, never data.
func writeFileAtomic(path string, data []byte, fileMode, dirMode os.FileMode) (err error) {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, dirMode); err != nil {
		return fmt.Errorf("create the folder %s: %w", dir, err)
	}
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*.tmp")
	if err != nil {
		return fmt.Errorf("create a temporary file in %s: %w", dir, err)
	}
	defer func() {
		if err != nil {
			_ = tmp.Close()
			_ = os.Remove(tmp.Name())
		}
	}()
	if _, err = tmp.Write(data); err != nil {
		return fmt.Errorf("write %s: %w", tmp.Name(), err)
	}
	if err = tmp.Chmod(fileMode); err != nil {
		return fmt.Errorf("set the mode of %s: %w", tmp.Name(), err)
	}
	if err = tmp.Sync(); err != nil {
		return fmt.Errorf("sync %s: %w", tmp.Name(), err)
	}
	if err = tmp.Close(); err != nil {
		return fmt.Errorf("close %s: %w", tmp.Name(), err)
	}
	if err = os.Rename(tmp.Name(), path); err != nil {
		return fmt.Errorf("replace %s: %w", path, err)
	}
	syncDir(dir)
	return nil
}

// syncDir flushes the folder entry written by the rename. Syncing the file
// alone does not make the new name durable: after a power cut the folder could
// still list the old file, and a password written just before it was sent to
// Nexus would be lost. It is best effort: Windows cannot open a folder for
// syncing and some file systems do not support it, and the file is already
// replaced either way, so every error is ignored.
func syncDir(dir string) {
	d, err := os.Open(dir)
	if err != nil {
		return
	}
	_ = d.Sync()
	_ = d.Close()
}
	repo := gitRepo(t)
	excludes := filepath.Join(t.TempDir(), "excludes")
	if err := os.WriteFile(excludes, []byte("secrets.json\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	t.Setenv("GIT_CONFIG_COUNT", "1")
	t.Setenv("GIT_CONFIG_KEY_0", "core.excludesFile")
	t.Setenv("GIT_CONFIG_VALUE_0", excludes)
	t.Setenv("GIT_CONFIG_PARAMETERS", "'core.excludesFile="+excludes+"'")

	if store, err := NewFileStore(filepath.Join(repo, "secrets.json")); err == nil {
		t.Fatalf("NewFileStore = %v, want a refusal: only the repository's own ignore rules count", store)
	}
}

func TestGitEnvironmentDropsTheConfigurationVariables(t *testing.T) {
	for _, name := range []string{"GIT_CONFIG_PARAMETERS", "GIT_CONFIG_COUNT", "GIT_CONFIG_KEY_0", "GIT_CONFIG_KEY_17", "GIT_CONFIG_VALUE_0", "GIT_CONFIG_VALUE_17", "GIT_CONFIG_SYSTEM", "GIT_CEILING_DIRECTORIES"} {
		t.Setenv(name, "/elsewhere")
	}
	t.Setenv("GIT_CONFIG_GLOBAL", "/elsewhere/gitconfig")
	t.Setenv("GIT_CONFIG_NOSYSTEM", "0")
	t.Setenv("DEVDESK_KEEP", "1")

	env := gitEnvironment()
	counts := map[string]int{}
	for _, kv := range env {
		name, _, _ := strings.Cut(kv, "=")
		upper := strings.ToUpper(name)
		counts[upper]++
		switch {
		case upper == "GIT_CONFIG_PARAMETERS", upper == "GIT_CONFIG_COUNT", upper == "GIT_CONFIG_SYSTEM", upper == "GIT_CEILING_DIRECTORIES",
			strings.HasPrefix(upper, "GIT_CONFIG_KEY_"), strings.HasPrefix(upper, "GIT_CONFIG_VALUE_"):
			t.Errorf("gitEnvironment keeps %s", kv)
		}
	}
	// No user configuration at all, whatever the caller had.
	if !slices.Contains(env, "GIT_CONFIG_GLOBAL="+os.DevNull) || counts["GIT_CONFIG_GLOBAL"] != 1 {
		t.Errorf("GIT_CONFIG_GLOBAL is not pinned to %s exactly once (seen %d)", os.DevNull, counts["GIT_CONFIG_GLOBAL"])
	}
	if !slices.Contains(env, "GIT_CONFIG_NOSYSTEM=1") || counts["GIT_CONFIG_NOSYSTEM"] != 1 {
		t.Errorf("GIT_CONFIG_NOSYSTEM is not pinned to 1 exactly once (seen %d)", counts["GIT_CONFIG_NOSYSTEM"])
	}
	if !slices.Contains(env, "DEVDESK_KEEP=1") {
		t.Error("gitEnvironment dropped a variable that is not about git")
	}
