			c, tool := newHelperSkopeo(t, map[string]string{helperStdoutEnv: "stdout-marker-77", helperStderrEnv: stderr, helperExitEnv: "1"})
			src := ImageRef{Transport: "oci", Location: "/var/tmp/layout:img-01"}
