	}
	if !strings.HasPrefix(rec.PolicyPath, tool.scratch) {
		t.Errorf("the policy %s is outside the temporary folder %s", rec.PolicyPath, tool.scratch)
	}
	var policy struct {
		Default []struct {
			Type string `json:"type"`
		} `json:"default"`
		Transports map[string]any `json:"transports"`
	}
