type skopeoCopier struct{ path string }

func NewSkopeoCopier() (ImageCopier, error) {
	p, err := exec.LookPath("skopeo")
	if err != nil {
		return nil, &BenchError{Kind: SkopeoMissing, Cause: "skopeo was not found on PATH", Check: "install skopeo", Err: err}
	}
	return &skopeoCopier{path: p}, nil
}

func (r ImageRef) arg() string {
	if r.Transport == "docker" {
		return "docker://" + r.Location
	}
	return r.Transport + ":" + r.Location
}

func checkLoopback(r ImageRef) error {
	if r.Transport != "docker" {
		return nil
	}
	host, _, _ := strings.Cut(r.Location, "/")
	h := host
	if strings.HasPrefix(h, "[") {
		if i := strings.Index(h, "]"); i > 0 {
			h = h[1:i]
		}
	} else if hh, _, err := net.SplitHostPort(h); err == nil {
		h = hh
	}
	if h == "localhost" || h == "::1" || h == "127.0.0.1" {
		return nil
	}
	return &BenchError{Cause: "not loopback", Check: "x"}
}

func skopeoEnvironment(registriesConf string) []string {
	var env []string
	for _, kv := range os.Environ() {
		name, _, _ := strings.Cut(kv, "=")
		u := strings.ToUpper(name)
		switch u {
		case "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "REGISTRY_AUTH_FILE":
			continue
		}
		if strings.HasPrefix(u, "CONTAINERS_") {
			continue
		}
		env = append(env, kv)
	}
	return append(env, "CONTAINERS_REGISTRIES_CONF="+registriesConf)
}

