	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, &BenchError{Kind: classifySkopeo(errb.String()), Cause: "skopeo failed", Check: "look", Err: err}
	}
	return out.Bytes(), nil
}

func writeAuth(dir string, creds map[string]*Credentials) (string, error) {
	auths := map[string]map[string]string{}
	for h, c := range creds {
		auths[h] = map[string]string{"auth": base64.StdEncoding.EncodeToString([]byte(c.User + ":" + c.Password))}
	}
	b, _ := json.Marshal(map[string]any{"auths": auths})
