	if err != nil {
		return "", err
	}
	_ = os.WriteFile(filepath.Join(dir, "policy.json"), []byte(`{"default":[{"type":"insecureAcceptAnything"}]}`), 0o600)
	_ = os.WriteFile(filepath.Join(dir, "registries.conf"), nil, 0o600)
	return dir, nil
}

func host(r ImageRef) string { h, _, _ := strings.Cut(r.Location, "/"); return h }

func (c *skopeoCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
	dir, err := c.prepare(src, dst)
	if err != nil {
		return err
	}
	defer os.RemoveAll(dir)
	args := []string{"--policy", filepath.Join(dir, "policy.json"), "copy"}
	if o.PreserveDigests {
		args = append(args, "--preserve-digests")
	}
	creds := map[string]*Credentials{}
	for _, s := range []struct {
		n string
		r ImageRef
		c *Credentials
	}{{"src", src, o.SrcCreds}, {"dest", dst, o.DestCreds}} {
		if s.r.Transport == "docker" {
			args = append(args, "--"+s.n+"-tls-verify=false")
		}
		if s.c == nil {
			args = append(args, "--"+s.n+"-no-creds")
		} else {
			creds[host(s.r)] = s.c
		}
	}
	if len(creds) > 0 {
		p, err := writeAuth(dir, creds)
		if err != nil {
			return err
		}
		args = append(args, "--authfile", p)
	}
	args = append(args, src.arg(), dst.arg())
	_, err = c.run(ctx, args, dir, filepath.Join(dir, "registries.conf"))
	return err
}

func (c *skopeoCopier) ManifestDigest(ctx context.Context, ref ImageRef, creds *Credentials) (string, error) {
	dir, err := c.prepare(ref)
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(dir)
	args := []string{"--policy", filepath.Join(dir, "policy.json"), "inspect", "--raw"}
	if ref.Transport == "docker" {
		args = append(args, "--tls-verify=false")
	}
	if creds == nil {
		args = append(args, "--no-creds")
	} else {
		p, err := writeAuth(dir, map[string]*Credentials{host(ref): creds})
		if err != nil {
			return "", err
		}
		args = append(args, "--authfile", p)
	}
	args = append(args, ref.arg())
	out, err := c.run(ctx, args, dir, filepath.Join(dir, "registries.conf"))
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(out)
	return "sha256:" + hex.EncodeToString(sum[:]), nil
}

