		switch u {
		case "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "REGISTRY_AUTH_FILE":
			continue
		}
		if strings.HasPrefix(u, "CONTAINERS_") {
